import{c as a,Q as t,j as n,m as s}from"./chunks/framework.BXc4yaFE.js";const c=JSON.parse('{"title":"Rethinking the Evaluation of Harness Evolution for Agents","description":"","frontmatter":{"url":"https://arxiv.org/abs/2607.12227","title":"Rethinking the Evaluation of Harness Evolution for Agents","archived_date":"2026-07-18T00:00:00.000Z","arxiv_id":2607.12227,"authors":["Yike Wang","Huaisheng Zhu","Zhengyu Hu","Yige Yuan","Zhengyu Chen","Shakti Senthil","Hannaneh Hajishirzi","Yulia Tsvetkov","Pradeep Dasigi","Teng Xiao"],"pdf_path":"pdfs/2607.12227.pdf","published_date":"2026-07-14T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2026-07-14-rethinking-evaluation-harness-evolution-agents-2607-12227.md","filePath":"research/papers/2026-07-14-rethinking-evaluation-harness-evolution-agents-2607-12227.md","lastUpdated":1785909234000}'),r={name:"research/papers/2026-07-14-rethinking-evaluation-harness-evolution-agents-2607-12227.md"};function i(o,e,h,l,u,g){return t(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="rethinking-the-evaluation-of-harness-evolution-for-agents" tabindex="-1">Rethinking the Evaluation of Harness Evolution for Agents <a class="header-anchor" href="#rethinking-the-evaluation-of-harness-evolution-for-agents" aria-label="Permalink to &quot;Rethinking the Evaluation of Harness Evolution for Agents&quot;">​</a></h1><p><strong>Authors</strong>: Yike Wang, Huaisheng Zhu, Zhengyu Hu, Yige Yuan, Zhengyu Chen, Shakti Senthil, Hannaneh Hajishirzi, Yulia Tsvetkov, Pradeep Dasigi, Teng Xiao <strong>Published</strong>: July 2026 <strong>Source</strong>: <a href="https://arxiv.org/abs/2607.12227" target="_blank" rel="noreferrer">https://arxiv.org/abs/2607.12227</a><strong>arXiv ID</strong>: 2607.12227 <strong>Categories</strong>: Computer Science &gt; Artificial Intelligence (cs.AI) <strong>PDF</strong>: <a href="https://arxiv.org/abs/2607.12227" target="_blank" rel="noreferrer">research/papers/pdfs/2607.12227.pdf</a></p><hr><h2 id="abstract" tabindex="-1">Abstract <a class="header-anchor" href="#abstract" aria-label="Permalink to &quot;Abstract&quot;">​</a></h2><p>This work reexamines how researchers evaluate automated harness evolution for large language model agents. The authors identify two key problems with current evaluation approaches: first, harness evolution involves iterative refinement but isn&#39;t properly compared against simpler baseline methods using equivalent computational resources; second, evaluating on the same benchmark used during development risks inflated performance claims. To address these gaps, the team conducted extensive experiments comparing harness evolution to basic test-time scaling methods on Terminal-Bench 2.1 using GPT-5.4 and Claude Opus 4.6. They also tested whether improvements transfer to previously unseen tasks. Their findings indicate that automatic harness evolution does not consistently outperform simple test-time scaling methods and exhibits limited generalization, suggesting the need for more rigorous evaluation standards in this research area.</p><hr><h2 id="core-thesis" tabindex="-1">Core Thesis <a class="header-anchor" href="#core-thesis" aria-label="Permalink to &quot;Core Thesis&quot;">​</a></h2><ul><li>質疑「harness evolution 一定優於簡單基準」的常見假設：在等算力預算下與 test-time scaling baseline 比較，發現自動 harness 演化並未一致勝出。</li><li>指出兩大評測缺陷：(1) 未用等資源基準比較迭代式 harness 演化，(2) 用開發集同一 benchmark 評測導致效能虛高（train-test 洩漏風險）。</li><li>用 Terminal-Bench 2.1（GPT-5.4、Claude Opus 4.6）實測，額外驗證跨任務泛化能力有限。</li><li><strong>Workspace 關聯</strong>：直接呼應 core.md 的「自報成功鏈」與 TEST 章「靜態 ≠ 端到端」規則——harness 自我進化宣稱的改善若未經 held-out 驗證即為 unverified_success；對本 workspace 的 <code>/autoload-evolution</code>、<code>harness-meta</code> 自我改進迴圈是重要方法論警示（eval on dev set ≈ 洩漏，需 sealed test）。</li></ul>',8)])])}const p=a(r,[["render",i]]);export{c as __pageData,p as default};
